package streammux

import (
	"bytes"
	"encoding/hex"
	"encoding/json"
	"os"
	"testing"
)

// goldenFile is generated by tools/gen-goldens/gen-goldens.mjs, which drives
// the real TypeScript StreamMux encoder from a WAADRI/node-proxy checkout.
// These tests are the byte-level compatibility gate between the Go rewrite
// and the deployed TS peers: decode the TS bytes, then re-encode our frames
// and demand identical output.
type goldenFile struct {
	Source struct {
		Repo   string `json:"repo"`
		File   string `json:"file"`
		Commit string `json:"commit"`
	} `json:"source"`
	Cases []goldenCase `json:"cases"`
}

type goldenCase struct {
	Name    string        `json:"name"`
	Kind    string        `json:"kind"` // "single" | "batch"
	WireHex string        `json:"wire_hex"`
	Frames  []goldenFrame `json:"frames"`
}

type goldenFrame struct {
	Type       uint32 `json:"type"`
	StreamID   uint32 `json:"stream_id"`
	Flags      uint32 `json:"flags"`
	PayloadHex string `json:"payload_hex"`
}

func loadGolden(t *testing.T) goldenFile {
	t.Helper()
	data, err := os.ReadFile("testdata/golden.json")
	if err != nil {
		t.Fatalf("read golden file: %v", err)
	}
	var g goldenFile
	if err := json.Unmarshal(data, &g); err != nil {
		t.Fatalf("parse golden file: %v", err)
	}
	if len(g.Cases) == 0 {
		t.Fatal("golden file has no cases")
	}
	return g
}

func TestGoldenVectors(t *testing.T) {
	g := loadGolden(t)
	t.Logf("golden source: %s@%s (%d cases)", g.Source.File, g.Source.Commit, len(g.Cases))

	for _, tc := range g.Cases {
		t.Run(tc.Name, func(t *testing.T) {
			wire, err := hex.DecodeString(tc.WireHex)
			if err != nil {
				t.Fatalf("bad wire_hex: %v", err)
			}

			// 1. Decode: the Go parser must accept the TS bytes and see the
			// frames recorded in the golden file.
			frames, err := ParseMessage(wire)
			if err != nil {
				t.Fatalf("ParseMessage: %v", err)
			}
			if len(frames) != len(tc.Frames) {
				t.Fatalf("decoded %d frames, want %d", len(frames), len(tc.Frames))
			}
			for i, want := range tc.Frames {
				got := frames[i]
				if got.Type != FrameType(want.Type) {
					t.Errorf("frame %d type = %s(%d), want %d", i, got.Type, got.Type, want.Type)
				}
				if got.StreamID != want.StreamID {
					t.Errorf("frame %d stream_id = %d, want %d", i, got.StreamID, want.StreamID)
				}
				if got.Flags != want.Flags {
					t.Errorf("frame %d flags = %#x, want %#x", i, got.Flags, want.Flags)
				}
				if payload := mustHex(t, want.PayloadHex); !bytes.Equal(got.Payload, payload) {
					t.Errorf("frame %d payload = %x, want %x", i, got.Payload, payload)
				}
			}

			// 2. Re-encode: Go output must be byte-identical to the TS bytes.
			var reencoded []byte
			var encErr error
			if tc.Kind == "batch" {
				reencoded, encErr = EncodeBatch(frames)
			} else {
				if len(frames) != 1 {
					t.Fatalf("single case has %d frames", len(frames))
				}
				reencoded, encErr = frames[0].Encode()
			}
			if encErr != nil {
				t.Fatalf("re-encode: %v", encErr)
			}
			if !bytes.Equal(reencoded, wire) {
				t.Fatalf("re-encode mismatch\n got: %x\nwant: %x", reencoded, wire)
			}
		})
	}
}

// TestGoldenJSONPayloadDecoding sanity-checks the typed payload structs
// against the JSON the TS encoder actually emitted.
func TestGoldenJSONPayloadDecoding(t *testing.T) {
	g := loadGolden(t)
	byName := make(map[string]goldenCase, len(g.Cases))
	for _, tc := range g.Cases {
		byName[tc.Name] = tc
	}

	t.Run("tunnel_open", func(t *testing.T) {
		frames := mustDecodeCase(t, byName["tunnel_open"])
		var open TunnelOpen
		if err := ParseJSONPayload(frames[0], &open); err != nil {
			t.Fatalf("ParseJSONPayload: %v", err)
		}
		if open.Host != "example.com" || open.Port != 443 {
			t.Fatalf("got %+v, want {example.com 443}", open)
		}
	})

	t.Run("ping", func(t *testing.T) {
		frames := mustDecodeCase(t, byName["ping"])
		var ping PingTime
		if err := ParseJSONPayload(frames[0], &ping); err != nil {
			t.Fatalf("ParseJSONPayload: %v", err)
		}
		if ping.Time != 1700000000123 {
			t.Fatalf("time = %d, want 1700000000123", ping.Time)
		}
	})

	t.Run("tunnel_close_string_reason", func(t *testing.T) {
		frames := mustDecodeCase(t, byName["tunnel_close_string_reason"])
		var r Reason
		if err := ParseJSONPayload(frames[0], &r); err != nil {
			t.Fatalf("ParseJSONPayload: %v", err)
		}
		if s, ok := r.Reason.(string); !ok || s != "target_closed" {
			t.Fatalf("reason = %#v, want \"target_closed\"", r.Reason)
		}
	})
}

func mustDecodeCase(t *testing.T, tc goldenCase) []Frame {
	t.Helper()
	wire, err := hex.DecodeString(tc.WireHex)
	if err != nil {
		t.Fatalf("bad wire_hex: %v", err)
	}
	frames, err := ParseMessage(wire)
	if err != nil || len(frames) == 0 {
		t.Fatalf("ParseMessage: %v frames, err %v", len(frames), err)
	}
	return frames
}

func mustHex(t *testing.T, s string) []byte {
	t.Helper()
	b, err := hex.DecodeString(s)
	if err != nil {
		t.Fatalf("bad hex %q: %v", s, err)
	}
	return b
}
